namespace SpatialSurvivor {
public sealed partial class SurvivorUI {
 ScreenState libraryReturn=ScreenState.Menu;int libraryIndex;GameObject previewRoot,previewModel;Camera previewCamera;RenderTexture previewTexture;float previewClock;
 void OpenLibrary(ScreenState page){libraryReturn=game.screen;libraryIndex=0;game.screen=page;}
