 void LibraryTabs(){Action("技能手册",-366,181,348,48,()=>{libraryIndex=0;game.screen=ScreenState.Skills;previous=(ScreenState)(-1);},game.screen==ScreenState.Skills);Action("生物图鉴",0,181,348,48,()=>{libraryIndex=0;game.screen=ScreenState.Bestiary;previous=(ScreenState)(-1);},game.screen==ScreenState.Bestiary);Action("武器商店",366,181,348,48,()=>{libraryIndex=0;game.screen=ScreenState.Shop;previous=(ScreenState)(-1);},game.screen==ScreenState.Shop);}
 void SelectLibrary(int i){libraryIndex=i;previous=(ScreenState)(-1);}
 void BuildLibrary(){bool skills=game.screen==ScreenState.Skills,monsters=game.screen==ScreenState.Bestiary;Heading(skills?"魔法研习手册":monsters?"林间生物图鉴":"行者武器商店",skills?"收录全部 39 种魔法，查看作用、等级与进化条件。":monsters?"识别地面与空中生物，了解它们的习性和应对方法。":"金币 "+game.meta.coins+"   ·   永久解锁，装备后下一局携带。晶核用于永久强化。");LibraryTabs();
  int count=skills?SurvivorRules.Cards.Length:monsters?SurvivorBestiary.Creatures.Length:SurvivorArmory.Weapons.Length;libraryIndex=Mathf.Clamp(libraryIndex,0,count-1);int page=libraryIndex/6,pages=Mathf.CeilToInt(count/6f);for(int row=0;row<6;row++){int index=page*6+row;if(index>=count)break;string name=skills?SurvivorRules.Cards[index].title:monsters?SurvivorBestiary.Creatures[index].name:SurvivorArmory.Get(index).name;string badge=skills?RarityName(SurvivorRules.Cards[index].rarity):monsters?(SurvivorBestiary.Flying(index)?"空中":"地面"):(game.meta.equippedWeapon==index?"已装备":game.meta.OwnsWeapon(index)?"已拥有":SurvivorArmory.Get(index).cost+" 金币");Action(name+"\n"+badge,-370,109-row*57,340,50,()=>SelectLibrary(index),index==libraryIndex);}
  Image(panel.transform,"Library detail",new Vector2(187,-27),new Vector2(715,350),Card);
