  if(pages>1){Action("上一页",-460,-263,160,48,()=>SelectLibrary(((page+pages-1)%pages)*6));Copy(panel.transform,(page+1)+" / "+pages,-280,-263,130,45,20,Muted,TextAnchor.MiddleCenter);Action("下一页",-110,-263,160,48,()=>SelectLibrary(((page+1)%pages)*6));}
  Action("返回",410,-263,240,50,CloseLibrary);Footer(skills?"手持武器可在商店永久解锁；这里的魔法通过局内升级获得。":monsters?"后续波次会增强生物生命与速度；此处展示基础属性。":(string.IsNullOrEmpty(game.notice)?"生存时间、击杀与通关都会奖励金币；失败也可获得已赚取的奖励。":game.notice));
 }
