 void BuildCreatureDetail(int index){var creature=SurvivorBestiary.Creatures[index];DetailName(creature.name);CreatePreview("Art/Creatures/"+creature.model,true);Copy(panel.transform,creature.Flying?"飞行追击":"地面生物",310,77,360,32,21,Gold);Copy(panel.transform,creature.description,310,16,360,90,23,Cream);Copy(panel.transform,creature.tactic,310,-81,360,94,20,Muted);Copy(panel.transform,"生命 "+creature.health+"   伤害 "+creature.damage+"   速度 "+creature.speed.ToString("F2")+" m/s\n"+(index==4?"十分钟 Boss": "第 "+creature.wave+" 波起出现"),180,-168,655,56,19,Mint,TextAnchor.MiddleCenter);}
