 void CreatePreview(string resource,bool creature){var go=new GameObject("Actual model preview",typeof(RectTransform),typeof(RawImage));go.transform.SetParent(panel.transform,false);var rect=go.GetComponent<RectTransform>();rect.anchoredPosition=new Vector2(-43,-5);rect.sizeDelta=new Vector2(240,240);previewTexture=new RenderTexture(384,384,24,RenderTextureFormat.ARGB32);go.GetComponent<RawImage>().texture=previewTexture;go.GetComponent<RawImage>().raycastTarget=false;previewRoot=new GameObject("Library preview stage");previewRoot.transform.position=Vector3.one*1000;previewModel=Instantiate(Resources.Load<GameObject>(resource),previewRoot.transform);if(resource.EndsWith("ArcPistol")||resource.EndsWith("Scattergun"))previewModel.transform.localRotation=Quaternion.Euler(12,-55,0);foreach(var child in previewModel.GetComponentsInChildren<Transform>(true))child.gameObject.layer=31;var cameraObject=new GameObject("Preview camera",typeof(Camera));cameraObject.transform.SetParent(previewRoot.transform,false);previewCamera=cameraObject.GetComponent<Camera>();previewCamera.enabled=false;previewCamera.stereoTargetEye=StereoTargetEyeMask.None;previewCamera.targetTexture=previewTexture;previewCamera.cullingMask=1<<31;previewCamera.clearFlags=CameraClearFlags.SolidColor;previewCamera.backgroundColor=new Color(.08f,.07f,.15f,1);previewCamera.nearClipPlane=.01f;previewCamera.farClipPlane=5;previewCamera.orthographic=true;
  var renderer=previewModel.GetComponentInChildren<Renderer>();var bounds=renderer.bounds;var skin=renderer as SkinnedMeshRenderer;if(skin){var local=skin.sharedMesh.bounds;bounds=new Bounds(skin.transform.TransformPoint(local.center),Vector3.Scale(local.size,skin.transform.lossyScale));}previewCamera.orthographicSize=Mathf.Max(bounds.size.x,bounds.size.y)*.65f;previewCamera.transform.position=bounds.center+new Vector3(0,.04f,2);previewCamera.transform.LookAt(bounds.center);previewClock=0;previewCamera.Render();}
 void TickPreview(){if(!previewModel||!previewCamera)return;previewModel.transform.Rotate(0,Time.unscaledDeltaTime*16,0);var animator=previewModel.GetComponent<SurvivorCreatureAnimator>();if(animator)animator.Tick(Time.unscaledDeltaTime);previewClock-=Time.unscaledDeltaTime;if(previewClock<=0){previewClock=.1f;previewCamera.Render();}}
}
